  "stuSess.creditAppliedSuccess": "Na vaše stanje je dodano dobroimetje v višini €{amount}, ki se bo samodejno uporabilo pri naslednji uri.",
  "stuSess.refundContactNote": "Za vračilo se obrnite na <a href=\"mailto:info@tutlio.lt\" class=\"text-amber-800 underline\">info@tutlio.lt</a>.",
  "stuSess.refundSuccessStripeNote": "<p class=\"text-emerald-900 text-sm mb-2\">Imate vprašanja ali težave? Pišite na <a href=\"mailto:info@tutlio.lt\" class=\"underline font-medium\">info@tutlio.lt</a>.</p><p class=\"font-semibold text-emerald-900\">Vaše vračilo se je začelo obdelovati prek Stripe.</p><p class=\"text-emerald-800 mt-1\">Vračila na kartico običajno prispejo v približno <strong>5–10 delovnih dneh</strong> (odvisno od banke). Če vračila ne prejmete v običajnem roku, pišite na <a href=\"mailto:info@tutlio.lt\" class=\"text-emerald-900 underline font-medium\">info@tutlio.lt</a>.</p>",
  "stuSess.refundSuccessManualTutor": "<p>Videti je, da ta ura ni bila plačana prek Stripe v Tutlio (npr. z bančnim nakazilom ali gotovino). Samodejno vračilo tukaj ni na voljo.</p><p class=\"mt-2\">Za vračilo se dogovorite z inštruktorjem <strong>{tutor}</strong> — uporabite e-poštni naslov ali podatke iz rezervacij oziroma podatke, ki vam jih je posredoval inštruktor.</p>",
  "stuSess.refundSuccessManualOrg": "<p>Videti je, da ta ura ni bila plačana prek Stripe v Tutlio (npr. z bančnim nakazilom ali gotovino). Samodejno vračilo tukaj ni na voljo.</p><p class=\"mt-2\">Ker se učite prek organizacije, se obrnite na <strong>skrbnika organizacije</strong> (prek inštruktorja ali objavljenih kontaktnih podatkov organizacije).</p>",
  "stuSess.refundTutorFallback": "svojega inštruktorja",
