  "landing.footerSolutions": "Rešitve",
  "landing.footerResources": "Viri",
  "landing.faq.whatIsQ": "Kaj je Tutlio?",
  "landing.faq.whatIsA": "Tutlio je platforma za upravljanje inštrukcij, ki samostojnim inštruktorjem in inštrukcijskim šolam pomaga na enem mestu upravljati urnike, plačila, komunikacijo z učenci in spremljanje ur.",
  "landing.faq.whoForQ": "Komu je namenjen Tutlio?",
  "landing.faq.whoForA": "Tutlio je namenjen samostojnim inštruktorjem, učiteljem glasbe, učiteljem jezikov, inštruktorjem matematike, inštrukcijskim šolam in izobraževalnim centrom vseh velikosti.",
  "landing.faq.waitlistQ": "Kako deluje čakalni seznam učencev?",
  "landing.faq.waitlistA": "Ko učenec odpove uro, se sproščeni termin samodejno ponudi učencem na čakalnem seznamu. Termin dobi tisti, ki prvi potrdi - tako inštruktorji zaradi odpovedi nikoli ne izgubijo prihodka.",
  "landing.faq.freeTrialQ": "Ali je na voljo brezplačni preizkus?",
  "landing.faq.freeTrialA": "Da! Vsak nov uporabniški račun samodejno prejme 7 brezplačnih dni - koda ni potrebna. V preizkusnem obdobju ni zaračunavanja, prekličete pa lahko kadar koli.",
  "landing.faq.languagesQ": "Katere jezike podpira Tutlio?",
  "landing.faq.languagesA": "Tutlio je na voljo v {count} jezikih: {languages}.",
  "landing.faqTitle": "Pogosta vprašanja",
  "landing.feature.digital-business-card": "Digitalna vizitka",
  "landing.feature.digital-business-cardDesc": "Delite eno profesionalno stran, kjer vas učenci spoznajo, si ogledajo trenutne cene in razpoložljivost ter takoj pošljejo povpraševanje za uro.",
  "featuresIndex.newBadge": "Novo",
  "feature.digital-business-card.pageTitle": "Digitalna vizitka, ki zanimanje spremeni v povpraševanja za ure",
  "feature.digital-business-card.pageDesc": "Vsakemu bodočemu učencu ponudite eno urejeno povezavo s svojo predstavitvijo, urami, cenami, mnenji in trenutno razpoložljivostjo. Takoj izbere uro in termin - vi pa ne izgubljate povpraševanj v dolgih pogovorih.",
  "feature.digital-business-card.detailsTitle": "Vse, kar bodoči učenec potrebuje za odločitev",
  "feature.digital-business-card.oneLink": "Ena povezava za vaše celotno inštrukcijsko podjetje",
  "feature.digital-business-card.oneLinkDesc": "Razpršene profile na družbenih omrežjih, cenike in sporočila za rezervacije nadomestite z eno stranjo, ki jo lahko delite kjer koli.",
  "feature.digital-business-card.liveAvailability": "Razpoložljivost, ki ostaja ažurna",
  "feature.digital-business-card.liveAvailabilityDesc": "Prosti termini se pridobijo neposredno iz koledarja Tutlio, zato stranke pošiljajo povpraševanja le za termine, ko res želite poučevati.",
  "feature.digital-business-card.instantEnquiries": "Povpraševanja za ure med poučevanjem",
  "feature.digital-business-card.instantEnquiriesDesc": "Starš ali učenec izbere uro, način izvedbe in termin ter pusti svoje podatke. Celotno povpraševanje prejmete brez usklajevanja urnika.",
  "feature.digital-business-card.professionalBrand": "Profesionalen prvi vtis",
  "feature.digital-business-card.professionalBrandDesc": "Predstavite fotografijo, pristop k poučevanju, predmete, cene, preverjena mnenja in barve svoje znamke na strani, ki lepo deluje na vsakem telefonu.",
  "feature.digital-business-card.faq.whatShowsQ": "Kaj lahko prikažem na digitalni vizitki?",
  "feature.digital-business-card.faq.whatShowsA": "Predstavite lahko sebe, predmete, načine izvedbe ur, javne cene, proste termine v koledarju, lokacijo, jezike, povezave do družbenih omrežij in preverjena mnenja učencev.",
  "feature.digital-business-card.faq.howBookingWorksQ": "Ali stranka takoj rezervira potrjeno uro?",
  "feature.digital-business-card.faq.howBookingWorksA": "Stranka izbere uro in prosti termin ter pošlje popolno zahtevo za rezervacijo. Prejmete jo v Tutlio in lahko potrdite novega učenca, preden se ura doda v vaš urnik.",
  "feature.digital-business-card.faq.whereShareQ": "Kje naj delim stran?",
  "feature.digital-business-card.faq.whereShareA": "Uporabite jo na Instagramu, TikToku, v skupinah na Facebooku, oglasih, e-poštnih podpisih, sporočilih in kodah QR. Ena povezava ostaja ažurna tudi ob spremembi cen ali koledarja.",
  "feature.digital-business-card.demo.eyebrow": "Interaktivni predogled za stranko",
  "feature.digital-business-card.demo.title": "Preizkusite rezervacijo",
  "feature.digital-business-card.demo.desc": "Spodaj izberite uro in termin. Tako preprosto pot opravi nova stranka prek vaše deljene povezave.",
  "feature.digital-business-card.demo.profile": "Inštruktor matematike · 9.–12. razred",
