  "featuresIndex.subtitle": "Od načrtovanja ur in čakalnega seznama učencev do plačil Stripe, izdajanja računov in portalov za starše - celotna platforma za upravljanje inštrukcij na enem mestu.",
  "featuresIndex.metaDesc": "Funkcije Tutlio: pametni koledar, čakalni seznam učencev, plačila Stripe, opomniki, pravila odpovedi, sporočila, paketi in drugo za inštrukcijska podjetja.",
  "featuresIndex.deepTitle": "Podrobni vodniki po funkcijah",
