  "enterpriseSuccess.backHome": "Nazaj na domačo stran",
  "landing.leadSuccess": "Hvala! Oglasili se vam bomo.",
  "orgTutorPolicy.title": "Interna pravila za inštruktorje",
  "orgTutorPolicy.intro": "Pred uporabo platforme preberite interna pravila organizacije.",
  "orgTutorPolicy.acceptBtn": "Razumem",
  "orgTutorPolicy.viewBtn": "Oglej si interna pravila",
  "orgTutorPolicy.s1Title": "1. Splošne določbe",
  "orgTutorPolicy.s1Body": "Ta pravila urejajo vašo uporabo platforme Tutlio (»platforma«) kot učitelja ali inštruktorja (»inštruktor«). K uporabi platforme vas je povabila izobraževalna agencija, šola ali inštrukcijski center, ki ga zastopate (»organizacija«). Tehnično vzdrževanje in podporo platforme zagotavlja MB Tutlio. Z uporabo uporabniškega računa soglašate s temi pravili in pravilnikom o zasebnosti.",
  "orgTutorPolicy.s2Title": "2. Upravljanje uporabniškega računa in urnikov",
  "orgTutorPolicy.s2Intro": "Platforma je zasnovana tako, da vam ni treba porabljati časa za usklajevanje terminov ur z učenci.",
  "orgTutorPolicy.s2Link": "Enolična povezava: dodeljena vam je osebna povezava za rezervacijo ur (glede na predmete, ki jih poučujete), prek katere učenci načrtujejo ure.",
  "orgTutorPolicy.s2Calendar": "Sinhronizacija koledarja: vaša razpoložljivost je neposredno odvisna od integracije Google Calendar (2-smerna sinhronizacija). Osebno ste odgovorni za točnost in ažurnost prostih terminov, prikazanih v vašem koledarju. Platforma učencem ne dovoli rezervirati terminov, ki so v vašem koledarju označeni kot zasedeni.",
  "orgTutorPolicy.s2Security": "Varnost uporabniškega računa: vaš uporabniški račun je oseben. Prijavne podatke morate varovati in jih ne smete deliti s tretjimi osebami.",
  "orgTutorPolicy.s3Title": "3. Odpovedi ur in čakalni seznam",
  "orgTutorPolicy.s3Intro": "Platforma pomaga čim bolje zapolniti vaš urnik in se izogniti praznim terminom:",
  "orgTutorPolicy.s3Auto": "Če učenec odpove uro, platforma samodejno pošlje obvestilo (SMS/e-pošta) drugim učencem na vašem čakalnem seznamu in jim ponudi sproščeni termin. Vaše dodatno ukrepanje ni potrebno.",
  "orgTutorPolicy.s3Rules": "Pravila odpovedi ur (koliko vnaprej je odpoved mogoča in kakšne so posledice) določi vaša organizacija.",
  "orgTutorPolicy.s4Title": "4. Finance in plačila",
  "orgTutorPolicy.s4Intro": "Ni vam treba skrbeti za izdajanje računov ali pobiranje plačil od staršev:",
  "orgTutorPolicy.s4Advance": "Vsa plačila učencev (ali staršev) za vaše ure se zberejo vnaprej prek platforme in prenesejo neposredno vaši organizaciji.",
  "orgTutorPolicy.s4Confirmed": "Uro izvedete samo, ko je potrjena v sistemu (kar pomeni, da je že zaračunana).",
  "orgTutorPolicy.s4Contact": "Za plačo, razpored izplačil in druge finančne zadeve se obrnite neposredno na skrbnika organizacije. MB Tutlio z inštruktorji ne izvaja neposrednih finančnih transakcij.",
  "orgTutorPolicy.s5Title": "5. Varstvo osebnih podatkov učencev (GDPR)",
  "orgTutorPolicy.s5Intro": "Kot inštruktor imate dostop do osebnih podatkov učencev, internih zapiskov in učnih gradiv. Zavezujete se, da boste:",
  "orgTutorPolicy.s5Use": "Te podatke uporabljali izključno za organizacijo in izvedbo ur.",
  "orgTutorPolicy.s5NoCopy": "Opustili kopiranje, izvažanje ali razširjanje kontaktnih podatkov učencev ali staršev zunaj platforme.",
  "orgTutorPolicy.s5Notes": "Varovali interne zapise organizacije (zapiske o napredku učencev), ki so vidni samo vam in administraciji organizacije, ne pa učencem ali staršem.",
  "orgTutorPolicy.s5Termination": "Ob prenehanju vašega delovnega razmerja z organizacijo bo vaš dostop do teh podatkov takoj preklican.",
  "orgTutorPolicy.s6Title": "6. Tehnično delovanje in omejitev odgovornosti",
  "orgTutorPolicy.s6Body": "Uporaba platforme za nezakonite namene, razširjanje zlonamernih povezav v učnih gradivih ali drugo motenje sistema je prepovedano. MB Tutlio zagotavlja delovanje in tehnično vzdrževanje platforme, vendar ne prevzema odgovornosti za motnje zaradi vaše internetne povezave, okvar naprav ali nepravilno nastavljenega Google Calendar.",
  "orgTutorPolicy.s7Title": "7. Podpora in kontakti",
  "orgTutorPolicy.s7Org": "Za vprašanja o urnikih ur, plačah, dodelitvah učencev ali organizaciji dela se obrnite na skrbnika organizacije.",
  "orgTutorPolicy.s7Tech": "O tehničnih napakah platforme (nedelujoča sinhronizacija koledarja, neprejemanje obvestil) obvestite skrbnika organizacije, ki bo stopil v stik s tehnično podporo Tutlio.",
  "register.orgPolicyConsent": "Z uporabo naše platforme soglašate z",
  "register.orgPolicyLink": "internimi pravili",
