  "quiz.info.insight.solo.point1": "Prestavitev ure lahko sproži spremembe koledarja, sporočila in popravke plačil.",
  "quiz.info.insight.solo.point2": "Nepovezani zapiski podaljšajo odgovarjanje tudi na preprosto učenčevo vprašanje.",
  "quiz.info.insight.solo.point3": "En povezan potek dela ohranja čas za poučevanje, ko seznam učencev raste.",
  "quiz.info.insight.company.title": "Operativne ovire se v ekipi inštruktorjev množijo",
  "quiz.info.insight.company.body": "Majhen ročni korak postane velika ovira, ko ga ponavljajo vsak inštruktor, učenec in skrbnik.",
  "quiz.info.insight.company.point1": "Skupni urnik daje ekipi en zanesljiv vir podatkov za vsakodnevno delo.",
  "quiz.info.insight.company.point2": "Status ure bi se moral prenesti v plačilo inštruktorju, obračun in poročila brez ponovnega vnosa.",
  "quiz.info.insight.company.point3": "Jasne vloge omogočajo vsakomur delo brez dostopa do celotnega delovnega prostora podjetja.",
  "quiz.info.insight.school.title": "Šolska administracija je ena povezana veriga",
  "quiz.info.insight.school.body": "Pogodbe, evidence učencev, obroki, komunikacija s starši in računovodstvo vplivajo drug na drugega. Ločene datoteke to verigo prekinejo.",
  "quiz.info.insight.school.point1": "Status pogodbe bi moral biti viden ob učencu - ne v ločeni evidenci.",
  "quiz.info.insight.school.point2": "Razporedi obrokov potrebujejo jasno povezavo s pravim plačnikom in pogodbo.",
  "quiz.info.insight.school.point3": "Finančni podatki so uporabnejši, ko so že strukturirani za poročanje.",
  "quiz.visual.demoTitle": "Oglejte si delovni prostor Tutlio v uporabi",
  "quiz.visual.demoSubtitle.solo": "Prikaz koledarja, prisotnosti, plačil, računov in vaše javne strani inštruktorja v živo.",
  "quiz.visual.demoSubtitle.company": "Prikaz statistike ekipe, obremenitve inštruktorjev, plačil, sporočil in dostopa staršev v živo.",
  "quiz.visual.demoSubtitle.school": "Prikaz osrednjih evidenc, plačil, komunikacije in družinskega dostopa v živo.",
  "quiz.info.story.disclosure": "Ponazoritev poteka dela - ni izjava stranke",
  "quiz.info.story.solo.eyebrow": "Izkušnje inštruktorjev",
  "quiz.info.story.solo.title": "Manj administracije, več miru pred vsako uro",
  "quiz.info.story.solo.body": "Dva kratka primera, kako lahko en povezan delovni prostor spremeni teden samostojnega inštruktorja.",
  "quiz.info.story.solo.disclosure": "Ponazoritveni primeri izkušenj inštruktorjev",
  "quiz.info.story.solo.name1": "Rasa",
  "quiz.info.story.solo.role1": "Inštruktor matematike",
  "quiz.info.story.solo.story1": "»Ko so ure, podatki učencev in plačila na enem mestu, petkovih večerov ne porabljam več za sestavljanje pregleda tedna iz sporočil.«",
  "quiz.info.story.solo.name2": "Mantas",
  "quiz.info.story.solo.role2": "Inštruktor angleščine",
  "quiz.info.story.solo.story2": "»Pregleden koledar in opomniki mi omogočajo, da se osredotočim na pripravo odličnih ur, namesto da ponavljam isto administracijo.«",
  "quiz.info.story.company.eyebrow": "Izkušnja stranke Tutlio",
  "quiz.info.story.school.eyebrow": "Izkušnja stranke Tutlio",
  "quiz.info.story.company.title": "Kaj se je spremenilo za ekipo PRO KLASĖ",
  "quiz.info.story.company.body": "Njihova ureditev združuje urnike, spremljanje ur in pravila plačil po meri v en vsakdanji potek dela.",
  "quiz.info.story.company.disclosure": "Potek dela stranke",
  "quiz.info.story.school.disclosure": "Potek dela stranke",
  "quiz.info.story.company.brandAlt": "Logotip PRO KLASĖ",
  "quiz.info.story.company.customerName": "PRO KLASĖ",
  "quiz.offer.testimonial.company.name1": "PRO KLASĖ",
  "quiz.info.story.company.customerType": "Ekipa inštrukcijske organizacije",
  "quiz.offer.testimonial.company.role1": "Ekipa inštrukcijske organizacije",
  "quiz.info.story.company.story": "»Pred Tutlio so bile spremembe ur, komentarji in ure inštruktorjev razpršeni po sporočilih. Zdaj celotna ekipa uporablja isti urnik in nam ob koncu meseca ni treba iskati posodobitev.«",
  "quiz.info.story.company.proof1": "Načrtovanje urnika ekipe",
  "quiz.info.story.company.proof2": "Pravila plačil po meri",
  "quiz.info.story.company.proof3": "Nadzor nad urami",
  "quiz.info.story.company.detail": "»Največja razlika je bila prilagoditev odobritev, nadomestnih ur in pravil plačil načinu, kako naša ekipa že dela, namesto da bi nas silili v splošen postopek.«",
  "quiz.info.story.school.title": "Kaj se je spremenilo za VšĮ “Laisvi vaikai”",
  "quiz.info.story.school.body": "Njihova ekipa povezuje evidence učencev, pogodbe, obroke in računovodstvo v en administrativni potek.",
  "quiz.info.story.school.brandAlt": "Logotip VšĮ “Laisvi vaikai”",
  "quiz.info.story.school.customerName": "VšĮ “Laisvi vaikai”",
  "quiz.offer.testimonial.school.name1": "VšĮ “Laisvi vaikai”",
  "quiz.info.story.school.customerType": "Šolska administrativna ekipa",
  "quiz.offer.testimonial.school.role1": "Šolska administrativna ekipa",
  "quiz.info.story.school.story": "»Želeli smo eno mesto, kjer bi ekipa spremljala družino od vpisa in pogodbe skozi vsak obrok. Tutlio nam zagotavlja to povezanost brez vzdrževanja vzporednih preglednic.«",
  "quiz.info.story.school.proof1": "Pogodbe in podpisi",
  "quiz.info.story.school.proof2": "Razporedi obrokov",
  "quiz.info.story.school.proof3": "Izvozi za računovodstvo",
  "quiz.info.story.school.detail": "»Najjasnejša izboljšava je vpogled v status pogodbe, podpisa in plačila, ne da bi morali spraševati več ljudi ali preverjati ločene datoteke.«",
  "quiz.offer.testimonial.school.copy1": "»Najjasnejša izboljšava je vpogled v status pogodbe, podpisa in plačila, ne da bi morali spraševati več ljudi ali preverjati ločene datoteke.«",
  "quiz.businessCard.eyebrow": "Vaša vgrajena stran za rast",
