  "quiz.offer.testimonial.solo.name3": "Ieva",
  "quiz.offer.testimonial.solo.role3": "Inštruktor kemije in biologije",
  "quiz.offer.testimonial.solo.copy3": "»Javna stran in rezervacija prek ene povezave pomagata novim učencem hitreje sprejeti odločitev, meni pa ni več treba vsakomur posebej pošiljati istih informacij.«",
  "quiz.offer.testimonial.solo.name4": "Lukas",
  "quiz.offer.testimonial.solo.role4": "Inštruktor fizike",
  "quiz.offer.testimonial.solo.copy4": "»V koledarju takoj vidim ure, spremembe in stanje plačil. Vsakodnevna administracija je postala precej krajša in preglednejša.«",
  "quiz.offer.testimonial.company.copy1": "»Spremembe ur, komentarji inštruktorjev in opravljene ure so prej prihajali v ločenih sporočilih. Zdaj administrativna ekipa vidi celotno sliko v enem urniku.«",
  "quiz.offer.testimonial.company.name2": "Samostojni inštrukcijski center",
  "quiz.offer.testimonial.company.role2": "Lastnik · 8 inštruktorjev",
  "quiz.offer.testimonial.company.copy2": "»Pred pripravo obračuna plačil so petkovi večeri minevali v primerjanju koledarja s sporočili inštruktorjev. S Tutlio je večina tega preverjanja že opravljena.«",
  "quiz.offer.testimonial.company.name3": "Studio za jezikovne inštrukcije",
  "quiz.offer.testimonial.company.role3": "Vodja poslovanja · 14 inštruktorjev",
  "quiz.offer.testimonial.company.copy3": "»Ko se ura prestavi, ekipa takoj vidi isto posodobitev. Manj je dodatnih sporočil, starši pa dobijo precej jasnejše odgovore.«",
  "quiz.offer.testimonial.company.name4": "Akademija za pripravo na izpite",
  "quiz.offer.testimonial.company.role4": "Finančni koordinator · 22 inštruktorjev",
  "quiz.offer.testimonial.company.copy4": "»Naša pravila za plačilo inštruktorjev se razlikujejo glede na vrsto ure, zato je konec meseca prej zahteval veliko ročnega preverjanja. Potek dela Tutlio je ta postopek precej umiril.«",
  "quiz.offer.testimonial.school.name2": "Neodvisna skupnostna šola",
  "quiz.offer.testimonial.school.role2": "Koordinator vpisa · 86 učencev",
  "quiz.offer.testimonial.school.copy2": "»Obdobje vpisov je včasih pomenilo spremljanje obrazcev, podatkov staršev in podpisanih pogodb v ločenih mapah. Zdaj naša ekipa vsako družino spremlja na enem mestu.«",
  "quiz.offer.testimonial.school.name3": "Center za obšolsko učenje",
  "quiz.offer.testimonial.school.role3": "Skrbnik · 120 učencev",
  "quiz.offer.testimonial.school.copy3": "»Razporedi obrokov so precej olajšali spremljanje plačil. Pred stikom s staršem vidim, kaj je zapadlo, namesto da bi seznam znova sestavljali ročno.«",
  "quiz.offer.testimonial.school.name4": "Šola za umetniško izobraževanje",
  "quiz.offer.testimonial.school.role4": "Finančni koordinator · 9 programov",
  "quiz.offer.testimonial.school.copy4": "»Izvoz za računovodstvo zdaj izhaja iz istih evidenc, ki jih uporabljamo za pogodbe in plačila, zato je ob koncu meseca veliko manj popravkov.«",
