  "nav.compare": "Primerjava",
  "landing.custom.badge": "Velika razlika",
  "landing.custom.title": "Programska oprema, ki se prilagodi vašemu načinu dela - in ne obratno",
  "landing.custom.sub": "Vsaka šola in agencija dela nekoliko drugače. Ko standardni potek ne ustreza, Tutlio prilagodimo vašemu procesu - običajno v tednih, ne v četrtletjih. Nekaj stvari, ki smo jih za stranke že izdelali:",
  "landing.custom.ex1Title": "Letne pogodbe z elektronskim podpisom",
  "landing.custom.ex1Desc": "Zasebna šola je potrebovala, da starši letne pogodbe podpisujejo elektronsko, plačujejo obročno in da se vsako plačilo prikaže v izvozu, pripravljenem za računovodstvo. Danes celoten cikel poteka znotraj Tutlia.",
  "landing.custom.ex2Title": "Pravila plačil in provizij inštruktorjev",
  "landing.custom.ex2Desc": "Agencija vsakemu inštruktorju plača glede na predmet in vrsto ure, zraven pa doda še provizijo podjetja. Njihova pravila smo modelirali, zato mesečni obračuni inštruktorjev in računi nastajajo samodejno.",
  "landing.custom.ex3Title": "Ponudbe za starše z enim klikom",
  "landing.custom.ex3Desc": "Šola je želela dodatne ure ponujati po e-pošti in staršem omogočiti, da jih sprejmejo z enim klikom - brez računa in brez tiskanja. Sprejem, obračun in vabilo na prvo uro zdaj potekajo sami.",
  "landing.custom.ex4Title": "Vaša znamka na vaši spletni strani",
  "landing.custom.ex4Desc": "Organizacija je želela svoj logotip in barve ter prijavo, vgrajeno v svojo spletno stran, da učenci in starši nikoli ne bi imeli občutka, da so jo zapustili. Tutlio danes teče pod njihovo znamko.",
  "landing.custom.note": "Nič od tega ni posebna izdaja. Vsaka prilagoditev postane del istega izdelka, ki ga vaša ekipa že uporablja, skupaj z vsemi prihodnjimi posodobitvami.",
  "landing.custom.cta": "Povejte nam, kako delate",
  "landing.custom.soloTitle": "Vam kaj manjka?",
  "landing.custom.soloNote": "Redno razvijamo funkcije za posamezne stranke - od enega pravila plačila do celotnega delovnega poteka. Povejte nam, kaj bi vam prihranilo čas.",
  "stats.cancellationPartTutor": "inštruktor: {count}",
  "compare.hub.badge": "Primerjava",
  "compare.hub.title": "Tutlio v primerjavi z drugimi programi za vodenje inštrukcij",
  "compare.hub.subtitle": "Poštene primerjave, točko za točko, z orodji, ki jih inštruktorji in inštrukcijski centri najpogosteje pretehtajo. Ko konkurent bolje ustreza, to povemo.",
  "compare.hub.metaTitle": "Tutlio vs TutorBird, TutorCruncher, Teachworks, Oases | Tutlio",
