  "compare.oases.metaDesc": "Tutlio vs Oases Online za inštrukcijske centre in programe z več enotami: cena po številu aktivnih učencev namesto licenc na inštruktorja, uparjanje, ocenjevanja, pogodbe, jeziki in prilagojene funkcije.",
  "compare.oases.intro1": "Oases Online je severnoameriška platforma za vodenje inštrukcijskih centrov, podjetij za pripravo na izpite, popoldanskih programov ter poslovanja z več enotami ali franšizami, vključno s ponudniki, ki delajo po javnih pogodbah. Pokriva urnik, uparjanje inštruktorja in učenca, izdajanje računov iz koledarja, plačila, ocenjevanja in poročila o napredku, portal za starše, tržna orodja in poslovna poročila.",
  "compare.oases.intro2": "Tutlio služi inštrukcijskim šolam in agencijam z lažjim in hitrejšim zagonom: koledar in samostojno rezerviranje, plačila prek Stripa in računi, pogodbe z obroki, plačila inštruktorjem, računi staršev, čakalni seznam, tabla in 36 jezikov vmesnika - s ceno na inštruktorja namesto na aktivnega učenca, s preizkusnim obdobjem in prilagojenimi funkcijami na zahtevo.",
